<?php use App\Models\Ticket; $scale=in_array($filters['scale']??'',['weeks','months','quarters'],true)?$filters['scale']:'months'; $origin=isset($filters['from'])?App\Core\Security::date($filters['from']):gmdate('Y-m-01'); $origin=$origin?:gmdate('Y-m-01'); $start=new DateTimeImmutable($origin); $days=match($scale){'weeks'=>42,'quarters'=>365,default=>120}; $step=match($scale){'weeks'=>7,'quarters'=>90,default=>30}; ?>
<div class="timeline-controls"><a class="button subtle" href="<?= e(query_url('/timeline',$baseQuery,['from'=>gmdate('Y-m-01')])) ?>">Aujourd’hui</a><div class="segmented"><?php foreach(['weeks'=>'Semaines','months'=>'Mois','quarters'=>'Trimestres'] as $v=>$l): ?><a class="<?= $scale===$v?'selected':'' ?>" href="<?= e(query_url('/timeline',$baseQuery,['scale'=>$v])) ?>"><?= e($l) ?></a><?php endforeach; ?></div><div class="toolbar-spacer"></div><a class="icon-button" aria-label="Période précédente" href="<?= e(query_url('/timeline',$baseQuery,['from'=>$start->modify('-'.$step.' days')->format('Y-m-d')])) ?>">←</a><span><?= e($start->format('d/m/Y')) ?> — <?= e($start->modify('+'.$days.' days')->format('d/m/Y')) ?></span><a class="icon-button" aria-label="Période suivante" href="<?= e(query_url('/timeline',$baseQuery,['from'=>$start->modify('+'.$step.' days')->format('Y-m-d')])) ?>">→</a></div>
<div class="timeline-panel"><div class="timeline-head"><div>Tickets <small>Dates et dépendances</small></div><div class="timeline-ruler"><?php for($d=0;$d<$days;$d+=$step): ?><span data-timeline-left="<?= round($d/$days*100,4) ?>"><?= e($start->modify('+'.$d.' days')->format($scale==='weeks'?'d M':'M Y')) ?></span><?php endfor; ?></div></div><?php foreach($tickets as $t): $s=$t['start_date']?new DateTimeImmutable($t['start_date']):null; $end=$t['due_date']?new DateTimeImmutable($t['due_date']):$s; $left=$s?((int)$start->diff($s)->format('%r%a')/$days*100):0; $width=$s&&$end?max(0.7,((int)$s->diff($end)->format('%r%a')+1)/$days*100):0; ?><div class="timeline-row" data-ticket-id="<?= (int)$t['id'] ?>" data-version="<?= (int)$t['version'] ?>" data-start-date="<?= e($t['start_date']) ?>" data-due-date="<?= e($t['due_date']) ?>"><a href="/tickets/<?= (int)$t['id'] ?>" class="timeline-task"><span class="type-icon type-<?= e($t['type']) ?>"><?= $t['type']==='epic'?'ϟ':'✓' ?></span><span><small><?= e($t['key']) ?></small><?= e($t['title']) ?></span></a><div class="timeline-track" data-timeline-origin="<?= e($origin) ?>" data-timeline-days="<?= $days ?>"><?php if($s&&$left<100&&$left+$width>0): ?><a class="timeline-bar status-<?= e($t['status']) ?>" href="/tickets/<?= (int)$t['id'] ?>" data-timeline-left="<?= max(0,$left) ?>" data-timeline-width="<?= min(100-max(0,$left),$width+min(0,$left)) ?>" title="<?= e($t['title'].' · '.$t['start_date'].' → '.$t['due_date']) ?>"><?= e($t['title']) ?></a><?php elseif(!$s): ?><button class="timeline-unscheduled" data-schedule-ticket="<?= (int)$t['id'] ?>">+ Planifier</button><?php endif; ?></div></div><?php endforeach; if(!$tickets): ?><div class="empty-state"><h3>Votre prochaine étape commence ici.</h3><p>Ajoutez un ticket ou ajustez les filtres.</p></div><?php endif; ?></div><div class="timeline-legend"><?php foreach(Ticket::STATUSES as $v=>$l): ?><span><i class="legend-dot status-<?= e($v) ?>"></i><?= e($l) ?></span><?php endforeach; ?><small>Ouvrez une barre pour modifier ses dates. Tous les types de tickets sont affichés.</small></div>
<dialog id="schedule-dialog" class="dialog compact"><form class="stack" data-schedule-form><header class="dialog-header"><h2>Donner une date au prochain pas</h2><button type="button" class="icon-button" data-close aria-label="Fermer"><?= icon('close') ?></button></header><input type="hidden" name="ticket_id"><label>Date de début<input type="date" name="start_date" required></label><label>Date d’échéance<input type="date" name="due_date" required></label><button class="button primary">Planifier</button></form></dialog>

<?php $timelineLinks=App\Core\DB::all("SELECT l.source_id,l.target_id FROM ticket_links l JOIN tickets t ON t.id=l.source_id WHERE t.project_id=? AND l.relation='blocks'",[$project['id']]); ?><script type="application/json" id="timeline-dependencies"><?= json_encode($timelineLinks,JSON_HEX_TAG|JSON_HEX_AMP|JSON_THROW_ON_ERROR) ?></script>
